/* @lc app=leetcode id=963 lang=kotlin */ class Solution { fun minAreaFreeRect(points: Array<IntArray>): Double = points.map { it[0] to it[1] }.toSet().let { s -> points.indices.flatMap { a -> points.indices.flatMap { b -> points.indices.filter { c -> a != b && a != c && b < c }.map { c -> Triple(points[a], points[b], points[c]) } } }.filter { (p, q, r) -> (q[0] - p[0]) * (r[0] - p[0]) + (q[1] - p[1]) * (r[1] - p[1]) == 0 && (q[0] + r[0] - p[0] to q[1] + r[1] - p[1]) in s }.minOfOrNull { (p, q, r) -> Math.abs((q[0] - p[0]).toLong() * (r[1] - p[1]) - (q[1] - p[1]).toLong() * (r[0] - p[0])) }?.toDouble() ?: 0.0 } }